const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),nodes=new Map(STORY.nodes.map(n=>[n.id,n])),records=new Map(RUN.records.map(r=>[r.nodeId,r])),skips=new Map(RUN.skipped.map(s=>[s.id,s.reason]));let shown=[],focused=null;
